        // 1. Try to get values explicitly set for this option
        List<Object> resultList = values.get(option);

        // 2. If no explicit values, try the provided defaultValues parameter
        if (resultList == null || resultList.isEmpty()) {
            if (defaultValues != null && !defaultValues.isEmpty()) {
                resultList = defaultValues;
            }
        }

        // 3. If still no values, try the internal defaultValues map
        if (resultList == null || resultList.isEmpty()) {
            List<Object> internalDefaultValues = this.defaultValues.get(option);
            if (internalDefaultValues != null && !internalDefaultValues.isEmpty()) {
                resultList = internalDefaultValues;
            }
        }

        // Ensure a non-null, mutable list is always returned.
        // If resultList is still null or empty, return an empty ArrayList.
        // Otherwise, return a new ArrayList containing the found values to prevent
        // external modification of internal map lists.
        return resultList == null || resultList.isEmpty() ? new ArrayList<>() : new ArrayList<>(resultList);
    }
