             * Wraps any IOException in a more descriptive runtime exception.
             *
             * @return The next CSVRecord, or null if no more records are available.
             * @throws IllegalStateException if an IOException occurs during reading,
             *                                indicating a problem with the underlying input stream.
             */
            private CSVRecord getNextRecordInternal() {
                try {
                    return CSVParser.this.nextRecord();
                } catch (final IOException e) {
                    // Provide a more specific and actionable error message.
                    throw new IllegalStateException(
                            "Failed to read next CSV record due to an I/O error. " +
                            "Original exception: " + e.getClass().getSimpleName() + " - " + e.getMessage(), e);
                }
            }

            @Override
            public boolean hasNext() {
                if (CSVParser.this.isClosed()) {
                    return false;
                }
                if (!hasCheckedNext) { // Only attempt to fetch if not already checked
                    this.current = this.getNextRecordInternal();
                    hasCheckedNext = true;
                }
                return this.current != null;
            }

            @Override
            public CSVRecord next() {
                if (CSVParser.this.isClosed()) {
                    throw new NoSuchElementException("CSVParser has been closed and cannot provide more records.");
                }

                // Ensure hasNext() has been called to pre-fetch 'current'
                if (!hasCheckedNext) {
                    // If next() is called without a preceding hasNext(), fetch the record.
                    // This aligns with the Iterator contract where next() can implicitly advance.
                    this.current = this.getNextRecordInternal();
                    hasCheckedNext = true; // Mark as checked
                }

                if (this.current == null) {
                    // If current is still null after attempting to fetch, there are no more elements.
                    throw new NoSuchElementException("No more CSV records available for iteration.");
                }

                CSVRecord nextRecordToReturn = this.current;
                this.current = null; // Consume the current record
                hasCheckedNext = false; // Reset flag, next hasNext() call will fetch a new record
                return nextRecordToReturn;
            }

            @Override
            public void remove() {
                throw new UnsupportedOperationException("Removing CSV records during iteration is not supported.");
            }
        };
    }
