@Override public void skipValue() throws IOException {
    if (peek() == JsonToken.NAME) {
        // If it's a name, we need to consume the name first, then skip its associated value.
        nextName(); // Consume the name
        // Now the current token is the value associated with the name.
        // We need to skip this value.
    }

    // Determine the type of the current value and skip it accordingly.
    // This uses a counter to handle nested arrays/objects.
    int count = 0;
    JsonToken token = peek();
    do {
        switch (token) {
            case BEGIN_ARRAY:
            case BEGIN_OBJECT:
                push(token == JsonToken.BEGIN_ARRAY ? JsonToken.END_ARRAY : JsonToken.END_OBJECT);
                count++;
                break;
            case END_ARRAY:
            case END_OBJECT:
                popStack(); // Pop the BEGIN_ARRAY/BEGIN_OBJECT marker
                count--;
                break;
            case NAME:
                // This case should ideally not be reached here if nextName() was called above.
                // If it is, it means we are inside an object and encountered another name.
                // We need to consume the name and then skip its value.
                nextName();
                break;
            case STRING:
            case NUMBER:
            case BOOLEAN:
            case NULL:
                popStack(); // Consume the primitive value
                break;
            case END_DOCUMENT:
                throw new IOException("Unexpected end of JSON document when skipping value.");
            default:
                // Should not happen with valid JSON and correct peek() implementation
                throw new AssertionError("Unexpected token: " + token);
        }
        // After processing a token, if we are still within a complex structure (count > 0),
        // we need to peek the next token to continue skipping.
        // If count is 0, it means we have skipped the entire current value.
        token = peek();
    } while (count != 0);

    // After skipping the value, increment the path index for the current level.
    // This applies whether the skipped value was a primitive, an array, or an object.
    pathIndices[stackSize - 1]++;
}
```

