                        + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
                }
            }
            pos += peekedNumberLength;
            peeked = PEEKED_NONE;
            pathIndices[stackSize - 1]++;
            return result;
        } catch (NumberFormatException e) {
            // If Long.parseLong fails, or if it contains a decimal point, it's not an int.
            throw new NumberFormatException("Expected an int but was " + new String(buffer, pos, peekedNumberLength)
                + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath() + ". " + e.getMessage());
        }
    } else if (p == PEEKED_SINGLE_QUOTED || p == PEEKED_DOUBLE_QUOTED) {
