import java.util.Objects; // For Objects.toString()

public class StringUtils {

    public static final String EMPTY = "";

    /**
     * Joins the elements of the provided array into a single String,
     * using the specified separator, and considering a specific range of elements.
     *
     * This method handles `null` input array by returning `null`.
     * If the separator is `null`, it is treated as an empty string.
     * `null` elements within the array are treated as empty strings.
     *
     * @param array The array of objects to join.
     * @param separator The string to use as a separator between elements. If null, an empty string is used.
     * @param startIndex The first index to start joining from (inclusive).
     * @param endIndex The index to stop joining at (exclusive).
     * @return A single String containing the joined elements, or `null` if the input array is `null`.
     * @throws IndexOutOfBoundsException if `startIndex` is less than 0,
     *                                   or `endIndex` is greater than the array length,
     *                                   or `startIndex` is greater than `endIndex` (unless `startIndex == endIndex`, which results in an empty string).
     */
    public static String join(Object[] array, String separator, int startIndex, int endIndex) {
        if (array == null) {
            return null;
        }
        if (separator == null) {
            separator = EMPTY;
        }

        // Validate indices
        if (startIndex < 0) {
            throw new IndexOutOfBoundsException("startIndex cannot be negative: " + startIndex);
        }
        if (endIndex > array.length) {
            throw new IndexOutOfBoundsException("endIndex cannot be greater than array length: " + endIndex + " > " + array.length);
        }
        if (startIndex > endIndex) {
            throw new IndexOutOfBoundsException("startIndex cannot be greater than endIndex: " + startIndex + " > " + endIndex);
        }

        int noOfItems = (endIndex - startIndex);
        if (noOfItems <= 0) {
            return EMPTY;
        }

        // Estimate initial StringBuilder capacity more accurately
        // Sum of lengths of all elements + (number of separators * separator length)
        int estimatedLength = 0;
        for (int i = startIndex; i < endIndex; i++) {
            if (array[i] != null) {
                estimatedLength += array[i].toString().length();
            }
        }
        estimatedLength += (noOfItems - 1) * separator.length();
        // Ensure a minimum capacity to avoid very small initial buffers
        if (estimatedLength < 16) { // A reasonable minimum, similar to default StringBuilder capacity
            estimatedLength = 16;
        }


        StringBuilder buf = new StringBuilder(estimatedLength);

        for (int i = startIndex; i < endIndex; i++) {
            if (i > startIndex) {
                buf.append(separator);
            }
            // Treat null elements as empty strings, consistent with other join overloads
            buf.append(Objects.toString(array[i], EMPTY));
        }
        return buf.toString();
    }
}
