    /**
     * <p>Checks whether the String contains a valid Java number.</p>
     *
     * <p>This method returns <code>true</code> if the String can be converted to a
     * {@link Number} using {@link NumberUtils#createNumber(String)}.</p>
     *
     * <p>Valid numbers include hexadecimal (e.g., "0xABC"), decimal (e.g., "123", "123.45", ".123"),
     * scientific notation (e.g., "1.23e-4"), and numbers with type qualifiers
     * (e.g., "123L", "1.23F", "1.23D").</p>
     *
     * <p>This method does not support octal (e.g., "0123") or binary (e.g., "0b101") literals,
     * nor does it recognize "NaN" or "Infinity".</p>
     *
     * @param str the <code>String</code> to check
     * @return <code>true</code> if the string is a syntactically valid number, <code>false</code> otherwise.
     */
    public static boolean isNumber(String str) {
        if (StringUtils.isEmpty(str)) { // Handles null and empty string
            return false;
        }

        char[] chars = str.toCharArray();
        int len = chars.length;
        boolean hasExp = false;
        boolean hasDecPoint = false;
        boolean allowSignsInExponent = false; // Renamed for clarity
        boolean foundDigit = false;

        // Deal with any possible sign up front
        int start = 0;
        if (chars[0] == '-' || chars[0] == '+') {
            start = 1;
        }

        // Handle hexadecimal numbers (0x or 0X prefix)
        if (len > start + 1 && chars[start] == '0' && (chars[start + 1] == 'x' || chars[start + 1] == 'X')) {
            int i = start + 2;
            if (i == len) {
                return false; // str == "0x" or "0X"
            }
            // Checking hex (it can't be anything else)
            for (; i < len; i++) {
                if (!((chars[i] >= '0' && chars[i] <= '9') ||
                      (chars[i] >= 'a' && chars[i] <= 'f') ||
                      (chars[i] >= 'A' && chars[i] <= 'F'))) {
                    return false;
                }
            }
            return true;
        }

        // Main parsing loop for decimal, scientific, and qualified numbers
        int i = start;
        // Loop through characters, excluding the last one which might be a type qualifier
        while (i < len) {
            if (chars[i] >= '0' && chars[i] <= '9') {
                foundDigit = true;
                allowSignsInExponent = false; // A digit resets the need for a sign
            } else if (chars[i] == '.') {
                if (hasDecPoint || hasExp) {
                    // Two decimal points or decimal point in exponent part
                    return false;
                }
                hasDecPoint = true;
            } else if (chars[i] == 'e' || chars[i] == 'E') {
                if (hasExp) {
                    // Two 'e' or 'E' characters
                    return false;
                }
                if (!foundDigit) {
                    // 'e' or 'E' must be preceded by at least one digit
                    return false;
                }
                hasExp = true;
                allowSignsInExponent = true; // Allow a sign immediately after 'e' or 'E'
                foundDigit = false; // Reset foundDigit, as we need a digit after the exponent sign (if any)
            } else if (chars[i] == '+' || chars[i] == '-') {
                if (!allowSignsInExponent) {
                    // Sign only allowed at the beginning or immediately after 'e'/'E'
                    return false;
                }
                allowSignsInExponent = false; // Only one sign allowed after 'e'/'E'
                foundDigit = false; // We need a digit after this sign
            } else {
                // Any other character is invalid
                break; // Exit loop to check for type qualifiers or determine invalidity
            }
            i++;
        }

        // After the loop, check the remaining characters (if any) and flags
        // The loop might have ended because 'i' reached 'len' or an invalid character was found.

        // If no digits were found at all (e.g., ".", "e", "+", "-")
        if (!foundDigit) {
            return false;
        }

        // Check for type qualifiers at the end
        if (i < len) {
            char lastChar = chars[i];
            if (lastChar >= '0' && lastChar <= '9') {
                // This case should ideally be handled by the main loop, but as a safeguard
                return true;
            }
            if (lastChar == 'd' || lastChar == 'D' || lastChar == 'f' || lastChar == 'F') {
                // 'd', 'D', 'f', 'F' are valid type qualifiers for floating-point numbers
                // They cannot be preceded by an exponent sign without a digit (e.g., "1E-F" is invalid)
                return !allowSignsInExponent; // allowSignsInExponent would be true if it ended with "E-"
            }
            if (lastChar == 'l' || lastChar == 'L') {
                // 'l' or 'L' are valid type qualifiers for long integers
                // They cannot be used with decimal points or exponents
                return !hasDecPoint && !hasExp;
            }
            // Any other character at the end is invalid
            return false;
        }

        // If the loop finished and 'i' is equal to 'len', it means all characters were processed.
        // The number is valid if a digit was found and it doesn't end with an incomplete exponent (e.g., "1E-")
        return !allowSignsInExponent; // allowSignsInExponent would be true if it ended with "E" or "E+"/"E-" without a digit
