                return 0; // Not enough characters after "&#"
            }

            char firstChar = input.charAt(start);
            if (firstChar == 'x' || firstChar == 'X') {
                start++;
                isHex = true;
            }

            // Check for sufficient length after 'x'/'X' for at least one digit and a semicolon
            if (start >= input.length()) {
                return 0; // Not enough characters after "&#x"
            }

            int end = start;
            // Find the end of the entity (semicolon)
            while (end < input.length() && input.charAt(end) != ';') {
                end++;
