     * decimal numbers (e.g., "123", "123.45", ".5", "5."),
     * scientific notation (e.g., "1.23e-10", "1E+5"),
     * and numbers with type qualifiers (e.g., "123L", "1.23f", "1.23D").</p>
     *
     * <p>This method is more lenient than {@link Double#parseDouble(String)}
     * or {@link Long#parseLong(String)} as it allows for type qualifiers
     * and hexadecimal prefixes.</p>
     *
     * @param str the String to check
     * @return {@code true} if the string is a valid number, {@code false} otherwise
     */
    public static boolean isNumber(String str) {
        if (StringUtils.isEmpty(str)) {
            return false;
        }

        char[] chars = str.toCharArray();
        int len = chars.length;
        int start = 0;

        // Handle leading sign
        if (chars[0] == '-' || chars[0] == '+') {
            start = 1;
        }

        // Handle hexadecimal numbers (e.g., "0xAF", "-0xAF", "+0xAF")
        if (len > start + 1 && chars[start] == '0' && (chars[start + 1] == 'x' || chars[start + 1] == 'X')) {
            int hexStart = start + 2;
            if (hexStart == len) {
                return false; // "0x" or "+0x" or "-0x"
            }
            for (int i = hexStart; i < len; i++) {
                if (!((chars[i] >= '0' && chars[i] <= '9') ||
                      (chars[i] >= 'a' && chars[i] <= 'f') ||
                      (chars[i] >= 'A' && chars[i] <= 'F'))) {
                    return false;
                }
            }
            return true;
        }

        boolean hasDecimalPoint = false;
        boolean hasExponent = false;
        boolean foundDigit = false;
        boolean allowSignAfterExponent = false; // Only true immediately after 'e' or 'E'

        // Iterate through the rest of the string
        for (int i = start; i < len; i++) {
            char c = chars[i];

            if (c >= '0' && c <= '9') {
                foundDigit = true;
                allowSignAfterExponent = false; // A digit invalidates the need for a sign after 'E'
            } else if (c == '.') {
                if (hasDecimalPoint || hasExponent) {
                    // Two decimal points, or decimal point after exponent
                    return false;
                }
                hasDecimalPoint = true;
            } else if (c == 'e' || c == 'E') {
                if (hasExponent || !foundDigit) {
                    // Two exponents, or exponent without any preceding digits
                    return false;
                }
                hasExponent = true;
                foundDigit = false; // Reset foundDigit, as we need a digit after the exponent
                allowSignAfterExponent = true; // Allow a sign immediately after 'e' or 'E'
            } else if (c == '+' || c == '-') {
                if (!allowSignAfterExponent) {
                    // Sign not allowed here (only allowed immediately after 'e' or 'E')
                    return false;
                }
                allowSignAfterExponent = false; // Only one sign allowed after 'E'
            } else {
                // Check for type qualifiers at the end
                if (i == len - 1) { // Only the last character can be a type qualifier
                    if (c == 'l' || c == 'L') {
                        // 'L' is not allowed with an exponent (as per original logic)
                        return foundDigit && !hasExponent;
                    }
                    if (c == 'f' || c == 'F' || c == 'd' || c == 'D') {
                        return foundDigit;
                    }
                }
                return false; // Invalid character
            }
        }

        // Final check: must have found at least one digit
        // And if allowSignAfterExponent is true, it means the string ended with 'E+' or 'E-', which is invalid.
        return foundDigit && !allowSignAfterExponent;
    }
