public static String getShortClassName(String className) {
    if (className == null || className.length() == 0) {
        return StringUtils.EMPTY;
    }

    // Handle array encoding: e.g., "[Ljava.lang.String;" -> "java.lang.String[]", "[[I" -> "int[][]"
    StringBuilder arraySuffix = new StringBuilder();
    int arrayDepth = 0;
    while (className.startsWith("[")) {
        className = className.substring(1);
        arrayDepth++;
    }
    if (arrayDepth > 0) {
        for (int i = 0; i < arrayDepth; i++) {
            arraySuffix.append("[]");
        }
        // Strip Object type encoding: e.g., "Ljava.lang.String;" -> "java.lang.String"
        if (className.startsWith("L") && className.endsWith(";")) {
            className = className.substring(1, className.length() - 1);
        } else {
            // Handle primitive types for arrays, e.g., "I" -> "int"
            if ("Z".equals(className)) {
                className = "boolean";
            } else if ("B".equals(className)) {
                className = "byte";
            } else if ("C".equals(className)) {
                className = "char";
            } else if ("D".equals(className)) {
                className = "double";
            } else if ("F".equals(className)) {
                className = "float";
            } else if ("I".equals(className)) {
                className = "int";
            } else if ("J".equals(className)) {
                className = "long";
            } else if ("S".equals(className)) {
                className = "short";
            } else if ("V".equals(className)) { // void is not a valid array component type, but for completeness
                className = "void";
            }
        }
    }

    int lastDotIdx = className.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
    int innerIdx = className.indexOf(
            INNER_CLASS_SEPARATOR_CHAR, lastDotIdx == -1 ? 0 : lastDotIdx + 1);
    String out = className.substring(lastDotIdx + 1);
    if (innerIdx != -1) {
        out = out.replace(INNER_CLASS_SEPARATOR_CHAR, PACKAGE_SEPARATOR_CHAR);
    }

    return out + arraySuffix.toString();
}
