    public static String abbreviate(String str, int lower, int upper, String appendToEnd) {
        if (str == null) {
            return null;
        }
        if (str.length() == 0) {
            return StringUtils.EMPTY;
        }

        // Normalize lower and upper bounds
        // Ensure lower is not negative
        lower = Math.max(0, lower);
        // Ensure upper is not negative (if -1 means no limit, handle it)
        // If upper is -1, it means no upper limit, so set to string length
        // Otherwise, ensure upper is not greater than string length
        upper = (upper == -1) ? str.length() : Math.min(upper, str.length());
        // Ensure upper is at least lower
        upper = Math.max(lower, upper);

        // If the effective upper bound is 0, return empty string (or appendToEnd if desired, but typically empty)
        if (upper == 0) {
            return StringUtils.EMPTY; // Or consider returning StringUtils.defaultString(appendToEnd) if 0 length implies abbreviation
        }

        // Find the first space within the effective range [lower, upper)
        // We search from 'lower' up to 'upper' to find a natural break point.
        // The substring will be from 0 up to this break point.
        int spaceIndex = StringUtils.indexOf(str, " ", lower);

        int effectiveEndIndex;
        boolean abbreviationOccurred;

        if (spaceIndex == -1 || spaceIndex > upper) {
            // No space found within the desired range, or the first space is beyond the upper limit.
            // Truncate at 'upper'.
            effectiveEndIndex = upper;
            abbreviationOccurred = (upper < str.length());
        } else {
            // A space was found within the desired range (lower <= spaceIndex <= upper).
            // Truncate at the space.
            effectiveEndIndex = spaceIndex;
            abbreviationOccurred = (spaceIndex < str.length());
        }

        // Build the result
        StringBuilder result = new StringBuilder();
        result.append(str.substring(0, effectiveEndIndex));

        // Append the suffix only if an actual abbreviation has occurred
        if (abbreviationOccurred) {
            result.append(StringUtils.defaultString(appendToEnd));
        }

        return result.toString();
    }
}
