public StrBuilder appendFixedWidthPadRight(Object obj, int width, char padChar) {
    // Only proceed if a positive width is specified.
    if (width <= 0) {
        return this; // No appending if width is not positive.
    }

    // Ensure enough capacity in the internal buffer for the new content.
    // We need space for 'width' characters.
    ensureCapacity(size + width);

    // Convert the object to a string. Handle null objects by using the configured nullText.
    String str = (obj == null) ? getNullText() : obj.toString();

    // Defensive check: if getNullText() somehow returns null, treat it as an empty string.
    // This prevents NullPointerException on str.length() or str.getChars().
    if (str == null) {
        str = "";
    }

    int strLen = str.length();

    if (strLen >= width) {
        // If the string is longer than or equal to the desired width,
        // truncate it and copy only the first 'width' characters.
        str.getChars(0, width, buffer, size);
    } else {
        // If the string is shorter than the desired width,
        // copy the entire string and then pad the remaining space.
        int padLen = width - strLen;
        str.getChars(0, strLen, buffer, size);
        // Pad the remaining characters on the right.
        for (int i = 0; i < padLen; i++) {
            buffer[size + strLen + i] = padChar;
        }
    }

    // Update the size of the StrBuilder to reflect the newly appended content.
    size += width;

    return this; // Return the StrBuilder instance for method chaining.
}
