    }

    // Ensure enough capacity in the internal buffer for the new content
    ensureCapacity(size + width);

    // Convert the object to its string representation. Handle null objects gracefully.
    final String str = (obj == null) ? getNullText() : obj.toString();
    final int strLen = str.length();

    if (strLen >= width) {
        // If the string is already wider than or equal to the desired width,
        // truncate it from the left to keep only the rightmost 'width' characters.
        str.getChars(strLen - width, strLen, buffer, size);
    } else {
