package org.apache.commons.lang3.text.translate;

import java.io.IOException;
import java.io.Writer;
import java.util.HashMap;
import java.util.Objects;

public class LookupTranslator extends CharSequenceTranslator {

    private final HashMap<CharSequence, CharSequence> lookupMap;
    private final int shortest;
    private final int longest;

    // Constructor (provided in the prompt, assuming it correctly initializes fields)
    public LookupTranslator(final CharSequence[]... lookup) {
        if (lookup == null) {
            throw new IllegalArgumentException("Lookup array cannot be null");
        }
        lookupMap = new HashMap<>();
        int currentShortest = Integer.MAX_VALUE;
        int currentLongest = 0;

        for (final CharSequence[] pair : lookup) {
            if (pair == null || pair.length != 2) {
                throw new IllegalArgumentException("Each lookup pair must contain two CharSequences.");
            }
            final CharSequence key = pair[0];
            final CharSequence value = pair[1];
            if (key == null || value == null) {
                throw new IllegalArgumentException("Lookup key and value cannot be null.");
            }
            lookupMap.put(key, value);
            final int len = key.length();
            if (len < currentShortest) {
                currentShortest = len;
            }
            if (len > currentLongest) {
                currentLongest = len;
            }
        }
        this.shortest = currentShortest;
        this.longest = currentLongest;
    }

    @Override
    public int translate(final CharSequence input, final int index, final Writer out) throws IOException {
        // Robustness Omissions: Input validation
        Objects.requireNonNull(input, "Input CharSequence cannot be null");
        Objects.requireNonNull(out, "Writer cannot be null");

        if (index < 0 || index > input.length()) {
            throw new IndexOutOfBoundsException("Index out of bounds: " + index + ", input length: " + input.length());
        }
        // If index is at the end of the input, there's nothing to translate.
        if (index == input.length()) {
            return 0;
        }

        int currentMaxSearchLength = longest;
        // Adjust max search length if it extends beyond the input's end
        if (index + longest > input.length()) {
            currentMaxSearchLength = input.length() - index;
        }

        // Descend so as to get a greedy algorithm (longest match first)
        for (int i = currentMaxSearchLength; i >= shortest; i--) {
            // Ensure we don't try to create a subsequence of negative or zero length if shortest is 0
            // or if currentMaxSearchLength becomes less than shortest due to input length constraints.
            if (i <= 0) { // This condition handles cases where shortest might be 0 or less, or currentMaxSearchLength is very small.
                continue;
            }
            // Ensure the subsequence end index is valid
            if (index + i > input.length()) {
                continue; // Should ideally be caught by currentMaxSearchLength, but as a safeguard.
            }

            final CharSequence subSeq = input.subSequence(index, index + i);
            final CharSequence result = lookupMap.get(subSeq);
            if (result != null) {
                out.write(result.toString());
                return i; // Return the number of characters consumed from the input
            }
        }
        return 0; // No translation found for the current index
    }
}
```

