public void stop() {
    // If the stopwatch is already stopped, do nothing (idempotent).
    // This prevents throwing an IllegalStateException if stop() is called multiple times.
    if (this.runningState == STATE_STOPPED) {
        return;
    }

    // Ensure the stopwatch is in a state where it can be stopped.
    // It must be running or suspended.
    if (this.runningState != STATE_RUNNING && this.runningState != STATE_SUSPENDED) {
        // Provide a more specific error message for clarity.
        String errorMessage;
        if (this.runningState == STATE_UNSTARTED) {
            errorMessage = "Stopwatch has not been started.";
        } else if (this.runningState == STATE_UNSPLIT || this.runningState == STATE_SPLIT) {
            // Assuming split states should also be handled, though the original didn't explicitly check.
            // A split stopwatch is still technically running, but stopping it might require unsplitting first
            // or the stop operation should implicitly handle the split state.
            // For simplicity, let's assume a split stopwatch can be stopped directly,
            // but if it's in an 'unsplit' state (which is a split-related state), it's not running.
            errorMessage = "Stopwatch is in an invalid state for stopping (e.g., split or unsplit).";
        } else {
            errorMessage = "Stopwatch is not running or suspended.";
        }
        throw new IllegalStateException(errorMessage);
    }

    // Synchronize access to shared state to ensure thread-safety.
    // This prevents race conditions when multiple threads try to stop the stopwatch.
    synchronized (this) {
        // Re-check state after acquiring lock, in case it changed between initial check and lock acquisition.
        if (this.runningState == STATE_STOPPED) {
            return; // Another thread might have stopped it already
        }
        if (this.runningState != STATE_RUNNING && this.runningState != STATE_SUSPENDED) {
            // This scenario is less likely with the initial check, but good for robustness.
            throw new IllegalStateException("Stopwatch state changed unexpectedly before stopping.");
        }

        stopTime = System.currentTimeMillis();
        this.runningState = STATE_STOPPED;
    }
}
