public StrBuilder appendFixedWidthPadRight(Object obj, int width, char padChar) {
    // Robustness: Handle negative or zero width explicitly.
    // If width is 0 or negative, no padding or appending should occur for fixed width.
    if (width <= 0) {
        // Return this to maintain method chaining, consistent with the original behavior
        // but now explicitly documented.
        return this;
    }

    // Robustness: Ensure capacity before converting to string to avoid potential issues
    // if toString() is very expensive and capacity check is cheap.
    // Also, ensures that if width is very large, capacity is handled upfront.
    ensureCapacity(size + width);

    String str;
    if (obj == null) {
        str = getNullText();
        // Robustness: If getNullText() returns null, treat it as an empty string
        // to prevent NullPointerException on str.length() or str.getChars().
        if (str == null) {
            str = "";
        }
    } else {
        str = obj.toString();
    }

    int strLen = str.length();

    if (strLen >= width) {
        // If the string is already wider than or equal to the desired width,
        // append the string as is, truncated to 'width' characters if it's longer.
        // The original code copies the full string if strLen >= width.
        // For "fixed width", it implies truncation if longer.
        // Let's assume the original intent was to append the full string if it fits or exceeds.
        // If truncation is desired, it would be: str.getChars(0, width, buffer, size);
        // Sticking to original behavior: append full string if it's >= width.
        str.getChars(0, strLen, buffer, size);
        size += strLen; // Update size by the actual length appended
    } else {
        // String is shorter than width, so append string and then pad.
        int padLen = width - strLen;
        str.getChars(0, strLen, buffer, size);
        for (int i = 0; i < padLen; i++) {
            buffer[size + strLen + i] = padChar;
        }
        size += width; // Update size by the fixed width
    }
    return this;
}
