        // Handle common BCP 47 language tags first (Java 7+)
        // This covers "en", "en-US", "en-Latn-US", "en-US-POSIX"
        // Note: Locale.forLanguageTag uses hyphens, but also handles underscores
        // for common cases like "en_US".
