        String mantissa;
        String decimalPart;
        String exponentPart;

        int decimalPointPos = str.indexOf('.');
        int expPosE = str.indexOf('e');
        int expPosUpperE = str.indexOf('E');

        // Determine the actual exponent position, taking the first one if both 'e' and 'E' exist
        int exponentIndicatorPos = -1;
        if (expPosE > -1) {
            exponentIndicatorPos = expPosE;
        }
        if (expPosUpperE > -1) {
            if (exponentIndicatorPos == -1 || expPosUpperE < exponentIndicatorPos) {
                exponentIndicatorPos = expPosUpperE;
            }
        }

        if (decimalPointPos > -1) {
            if (exponentIndicatorPos > -1) {
                if (exponentIndicatorPos < decimalPointPos) {
                    throw new NumberFormatException(str + " is not a valid number. Exponent indicator before decimal point.");
                }
                decimalPart = str.substring(decimalPointPos + 1, exponentIndicatorPos);
                mantissa = str.substring(0, decimalPointPos);
                exponentPart = str.substring(exponentIndicatorPos + 1);
            } else {
                decimalPart = str.substring(decimalPointPos + 1);
                mantissa = str.substring(0, decimalPointPos);
                exponentPart = null;
            }
        } else { // No decimal point
            if (exponentIndicatorPos > -1) {
                mantissa = str.substring(0, exponentIndicatorPos);
                exponentPart = str.substring(exponentIndicatorPos + 1);
                decimalPart = null;
            } else {
                mantissa = str;
                decimalPart = null;
                exponentPart = null;
