            // No specific type suffix, infer type
            boolean isEffectivelyZero = isAllZeros(mantissa) && (decimalPart == null || isAllZeros(decimalPart)) && (exponentPart == null || isAllZeros(exponentPart));

            if (decimalPointPos == -1 && exponentIndicatorPos == -1) {
